package cn.huankan.event;
import java.util.*;import java.time.Instant;import java.nio.charset.StandardCharsets;
import cn.huankan.evidence.EvidenceService;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class EntityMasterService {
 private final JdbcTemplate db;public EntityMasterService(JdbcTemplate db){this.db=db;}
 public record Candidate(String type,String originalName,String legalName,String chineseName,String country,String identifier,UUID evidenceId,String excerpt,Instant validFrom,Instant validTo){}
 private Map<String,Object> proof(UUID id,String excerpt){var r=db.queryForMap("SELECT r.*,s.level FROM raw_evidence r JOIN source_registry s ON s.id=r.source_id JOIN source_license l ON l.source_id=s.id WHERE r.id=? AND l.status='APPROVED' AND l.storage_allowed AND (l.valid_until IS NULL OR l.valid_until>now())",id);byte[] bytes=(byte[])r.get("raw_content");if(!EvidenceService.hash(bytes).equals(r.get("raw_content_hash"))||excerpt==null||excerpt.length()<5||excerpt.length()>4000||!new String(bytes,StandardCharsets.UTF_8).contains(excerpt))throw new IllegalArgumentException("真实证据摘录不足或哈希不一致");return r;}
 @Transactional public UUID candidate(Candidate c){if(c.type()==null||!Set.of("COUNTRY","REGION","CENTRAL_BANK","REGULATOR","ORGANIZATION","COMPANY","SECURITY","INDEX","COMMODITY","CURRENCY","INDUSTRY","SECTOR","INDICATOR","EXCHANGE","FUND").contains(c.type())||c.originalName()==null||c.originalName().isBlank()||c.originalName().length()>300||c.evidenceId()==null||c.validFrom()!=null&&c.validTo()!=null&&!c.validTo().isAfter(c.validFrom()))throw new IllegalArgumentException("实体或有效区间无效");var p=proof(c.evidenceId(),c.excerpt());if(!c.excerpt().contains(c.originalName())||c.identifier()!=null&&!c.excerpt().contains(c.identifier())||c.legalName()!=null&&!c.excerpt().contains(c.legalName()))throw new IllegalArgumentException("名称或标识没有对应摘录");UUID id=UUID.randomUUID();String key="evidence:"+c.evidenceId()+":"+c.originalName();db.update("INSERT INTO financial_entity(id,type,official_name,identity_key,chinese_name,source_id,source_url,evidence_id) VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(type,source_id,identity_key) DO NOTHING",id,c.type(),c.originalName(),key,c.chineseName(),p.get("source_id"),p.get("source_url"),c.evidenceId());id=db.queryForObject("SELECT id FROM financial_entity WHERE type=? AND source_id=? AND identity_key=?",UUID.class,c.type(),p.get("source_id"),key);db.update("INSERT INTO entity_profile_version(id,entity_id,legal_name,display_name_zh,original_name,country,official_identifier,evidence_id,valid_from,valid_to,excerpt) VALUES(?,?,?,?,?,?,?,?,?,?,?)",UUID.randomUUID(),id,c.legalName(),c.chineseName(),c.originalName(),c.country(),c.identifier(),c.evidenceId(),c.validFrom()==null?null:java.sql.Timestamp.from(c.validFrom()),c.validTo()==null?null:java.sql.Timestamp.from(c.validTo()),c.excerpt());return id;}
 public Object search(String q,int page){if(q==null||q.length()>200||page<0||page>100000)throw new IllegalArgumentException("搜索参数无效");return db.queryForList("SELECT e.*,p.legal_name,p.display_name_zh,p.country,p.official_identifier,p.review_status FROM financial_entity e LEFT JOIN LATERAL(SELECT * FROM entity_profile_version v WHERE v.entity_id=e.id ORDER BY created_at DESC LIMIT 1)p ON true WHERE (?='' OR e.official_name ILIKE '%'||?||'%') ORDER BY (e.status='VERIFIED') DESC,e.official_name,e.id LIMIT 50 OFFSET ?",q,q,page*50);}
 public Object detail(UUID id){return Map.of("entity",db.queryForMap("SELECT * FROM financial_entity WHERE id=?",id),"profiles",db.queryForList("SELECT p.*,r.source_url,r.published_at,r.raw_content_hash,(SELECT decision FROM entity_profile_review v WHERE v.profile_id=p.id ORDER BY created_at DESC,id DESC LIMIT 1) latest_review FROM entity_profile_version p JOIN raw_evidence r ON r.id=p.evidence_id WHERE entity_id=? ORDER BY created_at DESC LIMIT 100",id),"identifiers",db.queryForList("SELECT * FROM entity_identifier WHERE entity_id=? LIMIT 100",id),"securities",db.queryForList("SELECT * FROM security_profile_version WHERE entity_id=? ORDER BY created_at DESC LIMIT 100",id),"relations",db.queryForList("SELECT r.*,a.official_name subject,b.official_name object FROM entity_relation r JOIN financial_entity a ON a.id=r.subject_id JOIN financial_entity b ON b.id=r.object_id WHERE r.subject_id=? OR r.object_id=? LIMIT 100",id,id));}
 @Transactional public void support(UUID relation,UUID evidence,String excerpt){var p=proof(evidence,excerpt);db.update("INSERT INTO relation_support(relation_id,evidence_id,excerpt,source_url,published_at) VALUES(?,?,?,?,?)",relation,evidence,excerpt,p.get("source_url"),p.get("published_at"));}
 public Object relations(String kind){if(!Set.of("BUSINESS_FACT","INDUSTRY_MEMBERSHIP","MACRO_HYPOTHESIS","AI_CANDIDATE","STATISTICAL","ACCOUNTING_CONSOLIDATION","LEGAL_IDENTITY").contains(kind))throw new IllegalArgumentException("关系分类无效");return db.queryForList("SELECT r.*,a.official_name subject,b.official_name object,e.source_url,e.published_at,e.raw_content_hash FROM entity_relation r JOIN financial_entity a ON a.id=r.subject_id JOIN financial_entity b ON b.id=r.object_id LEFT JOIN raw_evidence e ON e.id=r.evidence_id WHERE r.relation_kind=? ORDER BY r.id LIMIT 100",kind);}
 @Transactional public UUID appendProfile(UUID entity,Candidate c){db.queryForObject("SELECT id FROM financial_entity WHERE id=?",UUID.class,entity);proof(c.evidenceId(),c.excerpt());if(c.originalName()==null||!c.excerpt().contains(c.originalName())||c.legalName()!=null&&!c.excerpt().contains(c.legalName())||c.identifier()!=null&&!c.excerpt().contains(c.identifier())||c.validFrom()!=null&&c.validTo()!=null&&!c.validTo().isAfter(c.validFrom()))throw new IllegalArgumentException("实体历史字段与证据不一致");UUID id=UUID.randomUUID();db.update("INSERT INTO entity_profile_version(id,entity_id,legal_name,display_name_zh,original_name,country,official_identifier,evidence_id,valid_from,valid_to,excerpt) VALUES(?,?,?,?,?,?,?,?,?,?,?)",id,entity,c.legalName(),c.chineseName(),c.originalName(),c.country(),c.identifier(),c.evidenceId(),c.validFrom()==null?null:java.sql.Timestamp.from(c.validFrom()),c.validTo()==null?null:java.sql.Timestamp.from(c.validTo()),c.excerpt());return id;}
 @Transactional public void reviewProfile(UUID profile,String decision,String reason,String actor){if(decision==null||!Set.of("VERIFIED","CONFLICT","EXPIRED","REJECTED").contains(decision)||reason==null||reason.length()<10||reason.length()>4000||actor==null||actor.isBlank()||actor.length()>200)throw new IllegalArgumentException("实体审核依据不足");db.update("INSERT INTO entity_profile_review(profile_id,decision,reason,actor) VALUES(?,?,?,?)",profile,decision,reason,actor);}
 public record Security(UUID exchangeId,String ticker,UUID issuerId,String listingStatus,Instant validFrom,Instant validTo,UUID evidenceId,String excerpt){}
 @Transactional public UUID security(UUID entity,Security s){if(!"SECURITY".equals(db.queryForObject("SELECT type FROM financial_entity WHERE id=?",String.class,entity))||s.ticker()==null||s.ticker().isBlank()||s.ticker().length()>100||s.listingStatus()==null||!Set.of("UNKNOWN","LISTED","DELISTED","PENDING").contains(s.listingStatus())||s.validFrom()!=null&&s.validTo()!=null&&!s.validTo().isAfter(s.validFrom()))throw new IllegalArgumentException("证券类型、代码或有效区间无效");proof(s.evidenceId(),s.excerpt());if(!s.excerpt().contains(s.ticker()))throw new IllegalArgumentException("证券代码缺少来源摘录");for(var id:List.of(s.exchangeId()==null?entity:s.exchangeId(),s.issuerId()==null?entity:s.issuerId())){String name=db.queryForObject("SELECT official_name FROM financial_entity WHERE id=?",String.class,id);if(!id.equals(entity)&&!s.excerpt().contains(name))throw new IllegalArgumentException("交易所或发行人没有对应证据");}UUID id=UUID.randomUUID();db.update("INSERT INTO security_profile_version(id,entity_id,exchange_id,ticker,issuer_id,listing_status,identifier_valid_from,identifier_valid_to,evidence_id,excerpt) VALUES(?,?,?,?,?,?,?,?,?,?)",id,entity,s.exchangeId(),s.ticker(),s.issuerId(),s.listingStatus(),s.validFrom()==null?null:java.sql.Timestamp.from(s.validFrom()),s.validTo()==null?null:java.sql.Timestamp.from(s.validTo()),s.evidenceId(),s.excerpt());return id;}
 public record Identity(UUID otherId,String decision,UUID evidenceId,String excerpt,String reason){}
 @Transactional public void identity(UUID entity,Identity i){if(i.decision()==null||!Set.of("SAME_ENTITY_CANDIDATE","DIFFERENT_ENTITY","NAME_CHANGE_CANDIDATE").contains(i.decision())||i.otherId()==null||entity.equals(i.otherId())||i.reason()==null||i.reason().length()<10)throw new IllegalArgumentException("身份消歧依据不足");proof(i.evidenceId(),i.excerpt());for(UUID id:List.of(entity,i.otherId()))if(!i.excerpt().contains(db.queryForObject("SELECT official_name FROM financial_entity WHERE id=?",String.class,id)))throw new IllegalArgumentException("身份对应证据未包含双方名称");db.update("INSERT INTO entity_identity_review(left_entity_id,right_entity_id,decision,evidence_id,excerpt,reason) VALUES(?,?,?,?,?,?)",entity,i.otherId(),i.decision(),i.evidenceId(),i.excerpt(),i.reason());}
}
